(function(){'use strict';function apply(){document.querySelectorAll('.edition').forEach(x=>{if(/v\d|MI.Y.R/i.test(x.textContent))x.textContent='MI’YĀR 5.0';});document.querySelectorAll('.main-footer span:first-child').forEach(x=>{const ar=document.documentElement.lang!=='en';x.textContent=ar?'معيار 5.0 · ذكاء القوى العاملة':'Miyar 5.0 · Workforce Intelligence';});}let queued=false;function schedule(){if(queued)return;queued=true;setTimeout(()=>{queued=false;apply();},0);}new MutationObserver(schedule).observe(document.documentElement,{subtree:true,childList:true});window.addEventListener('hashchange',schedule);window.addEventListener('miyar:navigate',schedule);document.addEventListener('DOMContentLoaded',schedule);schedule();window.MiyarReleaseVersion={version:'5.0.0',apply};})();